function main({
  product_requests_json,
  missing_fields_json,
  clarification_needed_text,
  follow_up_intent,
  scope_status,
  user_question,
  stored_product_requests,
  stored_follow_up_intent,
  stored_missing_fields
}) {
  let product_requests = [];
  let missing_fields = [];

  // --------------------------------------------------
  // 1. Parse extraction outputs
  // --------------------------------------------------

  try {
    const parsedProducts = JSON.parse(product_requests_json || "[]");
    product_requests = Array.isArray(parsedProducts)
      ? parsedProducts
      : [];
  } catch (e) {
    product_requests = [];
  }

  try {
    const parsedMissing = JSON.parse(missing_fields_json || "[]");
    missing_fields = Array.isArray(parsedMissing)
      ? parsedMissing
      : [];
  } catch (e) {
    missing_fields = [];
  }

  let clarification_needed =
    String(clarification_needed_text || "")
      .trim()
      .toLowerCase() === "true";

  let normalizedIntent =
    String(follow_up_intent || "none")
      .trim()
      .toLowerCase();

  let normalizedScope =
    String(scope_status || "unrelated")
      .trim()
      .toLowerCase();

  const storedRequests =
    Array.isArray(stored_product_requests)
      ? stored_product_requests
      : [];

  const question =
    String(user_question || "")
      .trim()
      .toLowerCase();


  // --------------------------------------------------
  // 2. Supported category whitelist
  // --------------------------------------------------

  const supportedCategories = {
    laptop: "Laptop",
    desktop: "Desktop",
    smartphone: "Smartphone",
    tablet: "Tablet",
    headphones: "Headphones",
    monitor: "Monitor",
    smartwatch: "Smartwatch",
    mouse: "Mouse",
    keyboard: "Keyboard"
  };


  // --------------------------------------------------
  // 3. Deterministically detect common follow-up intent
  // --------------------------------------------------

  let detectedIntent = "none";
  // Test negation immediately before each matched phrase. A negated cheaper
  // clause must not suppress an affirmative comparison in a later clause.
  const negatedPrefix = /\b(?:(?:do not|don't|does not|doesn't|no longer|never)\s+(?:want|need|recommend|suggest|show|give|ask for)|not|no)\s+(?:(?:a|an|any|the|something|anything)\s+)?$/;
  function hasAffirmativeComparison(pattern) {
    return [...question.matchAll(new RegExp(pattern.source, "g"))].some(match =>
      !negatedPrefix.test(question.slice(0, match.index)));
  }

  if (hasAffirmativeComparison(/\b(?:cheaper|more affordable|less expensive|lower[- ]priced)\b/)) {
    detectedIntent = "cheaper";
  } else if (hasAffirmativeComparison(/\b(?:more expensive|higher[- ]priced)\b/)) {
    detectedIntent = "more_expensive";
  } else if (hasAffirmativeComparison(/\b(?:alternative|another (?:one|option|product)|different (?:one|option|product)|other option)\b/)) {
    detectedIntent = "alternative";
  }

  // A complete, explicitly priced current purchase with no extracted comparison
  // intent takes priority over the old pending action and incidental keywords.
  const explicitCurrentPurchase = normalizedScope === "supported" && normalizedIntent === "none"
    && product_requests.length > 0 && getMissingFields(product_requests).length === 0
    && /\b(?:i (?:need|want)|i(?:'m| am) looking for|i(?:'d| would) like)\b/.test(question)
    && /\d/.test(question);

  const effectiveIntent =
    detectedIntent !== "none"
      ? detectedIntent
      : normalizedIntent;

  const isFollowUp =
    effectiveIntent === "cheaper" ||
    effectiveIntent === "more_expensive" ||
    effectiveIntent === "alternative";


  // --------------------------------------------------
  // 4. Resolve a comparison target without changing saved request facts
  // --------------------------------------------------
  // Recover only a bounded comparison phrase, not keyword matches in new tasks.
  const categoryKey = value => String(value || "").trim().toLowerCase();
  const categoryPattern = Object.keys(supportedCategories).join("|");
  const comparisonText = question.replace(/[.!?]+$/, "")
    .replace(/,\s*please$/, " please").replace(/\s+/g, " ");
  const comparisonPattern = new RegExp(
    "^(?:(?:please )?(?:(?:can|could|would) you (?:please )?)?"
    + "(?:recommend|suggest|show|give)(?: me)? |do you have |is there |are there |(?:can|could|may) i (?:get|have) )?"
    + "(?:a |an |any |anything |something )?"
    + "(cheaper|more affordable|less expensive|lower[- ]priced|more expensive|higher[- ]priced|alternative|another|different|other)"
    + "(?: (?:one|ones|option|options|product|products|(?:" + categoryPattern + ")"
    + "(?: (?:or|and) (?:" + categoryPattern + "))*(?: options?)?))?(?: please)?$"
  );
  const comparison = comparisonText.match(comparisonPattern);
  const categoryReply = comparisonText.match(new RegExp("^(?:the )?(" + categoryPattern + ")(?: please)?$"));
  const pendingIntent = categoryKey(stored_follow_up_intent);
  // Existing globals carry the pending action together. Intent alone is stale
  // history, never authorization to reinterpret a category-only message.
  const pendingTarget = Array.isArray(stored_missing_fields)
    && stored_missing_fields.includes("follow_up_target")
    && ["cheaper", "more_expensive", "alternative"].includes(pendingIntent);
  const extractedUnsupported = product_requests.some(request => {
    const key = categoryKey(request?.category);
    return key && !Object.prototype.hasOwnProperty.call(supportedCategories, key);
  });
  // Cancellation is a bounded conversation-control message, never a keyword
  // match inside a different request. Route it through the existing supported
  // writer so clearing the pending pair is persisted before the acknowledgement.
  const pendingDetails = Array.isArray(stored_missing_fields)
    && stored_missing_fields.includes("follow_up_details");
  const comparison_cancelled = (pendingTarget || pendingDetails)
    && /^(?:never ?mind(?:[,;]?\s+(?:please )?cancel (?:that|the|this) comparison)?|(?:please )?cancel (?:(?:(?:that|the|this) )?(?:comparison|follow[- ]?up)|that|it)|(?:please )?stop (?:that|the|this) comparison)(?: please)?$/.test(comparisonText);
  let targetCategory = "";
  let awaitingTarget = false;
  let clarificationField = "follow_up_target";
  const canResolve = normalizedScope !== "unsupported" && !extractedUnsupported
    && storedRequests.length > 0;

  if (comparison_cancelled) {
    product_requests = storedRequests.map(item => ({ ...item }));
    normalizedScope = "supported";
    normalizedIntent = "none";
    missing_fields = [];
    clarification_needed = false;
  } else if (canResolve && (comparison || (pendingTarget && categoryReply))) {
    const phrase = comparison?.[1] || "";
    normalizedIntent = comparison
      ? (/^(cheaper|more affordable|less expensive|lower[- ]priced)$/.test(phrase) ? "cheaper"
        : /^(more expensive|higher[- ]priced)$/.test(phrase) ? "more_expensive" : "alternative")
      : pendingIntent;
    normalizedScope = "supported";
    // These phrases contain no budget/usage edits. Saved facts take priority
    // over omitted or hallucinated extraction, including unrelated categories.
    product_requests = storedRequests.map(item => ({ ...item }));
    const mentioned = [...new Set(comparisonText.match(new RegExp("\\b(?:" + categoryPattern + ")\\b", "g")) || [])];
    if (mentioned.length === 1) targetCategory = mentioned[0];
    else if (mentioned.length === 0 && storedRequests.length === 1) targetCategory = categoryKey(storedRequests[0]?.category);
    awaitingTarget = !Object.prototype.hasOwnProperty.call(supportedCategories, targetCategory)
      || storedRequests.filter(item => categoryKey(item?.category) === targetCategory).length !== 1;
    if (awaitingTarget) targetCategory = "";
  } else if (canResolve && normalizedScope === "supported" && isFollowUp && !explicitCurrentPurchase
    && (storedRequests.length > 1 || product_requests.length === 0)) {
    // Unrecognized comparison wording must not apply one intent globally.
    // Field-update semantics are deliberately deferred to Phase 1B.2.
    product_requests = storedRequests.map(item => ({ ...item }));
    normalizedIntent = "none";
    clarificationField = "follow_up_details";
    awaitingTarget = true;
  } else if (normalizedScope === "supported" && comparison && !extractedUnsupported
    && storedRequests.length === 0) {
    // A bounded comparison contains no budget or usage facts. Without saved
    // context, retain only an explicit category rather than fabricated extraction.
    const mentioned = [...new Set(comparisonText.match(new RegExp("\\b(?:" + categoryPattern + ")\\b", "g")) || [])];
    product_requests = mentioned.length === 1
      ? [{ category: supportedCategories[mentioned[0]], budget: null, main_usage: null }] : [];
    normalizedIntent = "none";
    missing_fields = product_requests.length > 0 ? getMissingFields(product_requests)
      : ["category", "budget", "main_usage"];
    clarification_needed = true;
  }


  // --------------------------------------------------
  // 5. Category whitelist guard
  // --------------------------------------------------
  //
  // Supported categories are a hard business rule.
  // If the extractor returns Camera, TV, Printer, Router, etc.,
  // the request must be routed to unsupported instead of asking
  // clarification questions.
  // --------------------------------------------------

  let hasUnsupportedCategory = false;

  product_requests = product_requests.map(request => {
    if (!request || typeof request !== "object") {
      return request;
    }

    const rawCategory =
      String(request.category || "").trim();

    if (!rawCategory) {
      return request;
    }

    const canonicalCategory =
      Object.prototype.hasOwnProperty.call(supportedCategories, rawCategory.toLowerCase())
        ? supportedCategories[rawCategory.toLowerCase()] : undefined;

    if (!canonicalCategory) {
      hasUnsupportedCategory = true;
      return request;
    }

    return {
      ...request,
      category: canonicalCategory
    };
  });

  if (hasUnsupportedCategory) {
    normalizedScope = "unsupported";
    normalizedIntent = "none";
    clarification_needed = false;
    missing_fields = [];
  }


  // --------------------------------------------------
  // 6. Recalculate missing fields for supported requests
  // --------------------------------------------------

  const target_requests = normalizedScope === "supported" && !awaitingTarget && !comparison_cancelled
    ? product_requests.filter(request => !targetCategory || categoryKey(request?.category) === targetCategory)
    : [];

  if (
    normalizedScope === "supported" &&
    target_requests.length > 0
  ) {
    missing_fields = getMissingFields(target_requests);

    clarification_needed =
      missing_fields.length > 0;
  }


  // --------------------------------------------------
  // Pending state is consumed when a unique target resolves or a new supported
  // task overwrites these fields. Ordinary non-supported routes leave saved state
  // alone; explicit cancellation has already selected the supported writer path.
  if (normalizedScope === "supported" && awaitingTarget) {
    missing_fields = [clarificationField];
    clarification_needed = true;
  }

  // 7. Normalize allowed intent values
  // --------------------------------------------------

  const allowedIntents = [
    "none",
    "cheaper",
    "more_expensive",
    "alternative"
  ];

  if (!allowedIntents.includes(normalizedIntent)) {
    normalizedIntent = "none";
  }


  // --------------------------------------------------
  // 8. Normalize allowed scope values
  // --------------------------------------------------

  const allowedScopes = [
    "supported",
    "unsupported",
    "help",
    "unrelated"
  ];

  if (!allowedScopes.includes(normalizedScope)) {
    normalizedScope = "unrelated";
  }


  // --------------------------------------------------
  // 9. Return normalized state
  // --------------------------------------------------

  return {
    product_requests,
    target_requests,
    comparison_cancelled,
    skip_retrieval: clarification_needed || comparison_cancelled,
    missing_fields,
    clarification_needed,
    follow_up_intent: normalizedIntent,
    scope_status: normalizedScope
  };


  // --------------------------------------------------
  // Helper: determine missing required fields
  // --------------------------------------------------

  function getMissingFields(requests) {
    const missing = new Set();

    for (const request of requests) {
      if (
        !request ||
        !String(request.category || "").trim()
      ) {
        missing.add("category");
      }

      if (
        request == null ||
        request.budget === null ||
        request.budget === undefined ||
        String(request.budget).trim() === ""
      ) {
        missing.add("budget");
      }

      if (
        !request ||
        !String(request.main_usage || "").trim()
      ) {
        missing.add("main_usage");
      }
    }

    return Array.from(missing);
  }
}

