function main({
  user_question,
  active_requests,
  follow_up_intent,
  previous_recommendations
}) {
  const requests = Array.isArray(active_requests)
    ? active_requests
    : [];

  const previous = Array.isArray(previous_recommendations)
    ? previous_recommendations
    : [];

  if (requests.length === 0) {
    return {
      comparison_history: [],
      retrieval_query: String(user_question || "")
    };
  }

  const categoryKey = value =>
    String(value || "").trim().toLowerCase();

  const intent =
    String(follow_up_intent || "none").toLowerCase();

  const comparison_history = [];
  const queries = requests.map(request => {
    const category = request?.category || "";
    const budget = request?.budget ?? "";
    const mainUsage = request?.main_usage || "";

    const categoryMatches = previous.filter(item =>
      categoryKey(category) !== "" &&
      categoryKey(item?.category) === categoryKey(category)
    );
    const previousItem = categoryMatches.length === 1
      ? categoryMatches[0]
      : null;
    if (previousItem) comparison_history.push({ ...previousItem });

    const previousProduct =
      previousItem?.recommended_product || "";

    const previousPrice =
      previousItem?.price ?? "";

    let query =
      `${category} for ${mainUsage}`
      + (budget !== "" ? ` within RMB ${budget}` : "");

    if (intent === "cheaper" && previousPrice !== "") {
      query += `, cheaper than RMB ${previousPrice}`;
    } else if (
      intent === "more_expensive" &&
      previousPrice !== ""
    ) {
      query += `, more expensive than RMB ${previousPrice}`;
    } else if (
      intent === "alternative" &&
      previousProduct
    ) {
      query += `, alternative to ${previousProduct}`;
    }

    return query.trim();
  });

  return {
    comparison_history,
    retrieval_query: queries.join("\n")
  };
}
